SELECT advance.* FROM hr_employee_advance advance
JOIN hr_employee employee ON employee.id = advance.employee_id
    AND employee.tenant_id = advance.tenant_id AND employee.deleted = 0
WHERE advance.tenant_id = #{tenantId}



        AND employee.dept_id IN
        #{departmentId}

    AND employee.dept_id = #{scope.deptId}
    AND employee.user_id = #{scope.userId}
    AND 1 = 0

AND advance.employee_id = #{query.employeeId}
AND advance.status = #{query.status}
AND advance.approval_status = #{query.approvalStatus}

    AND (advance.advance_no LIKE CONCAT('%', #{query.keyword}, '%') OR employee.name LIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY advance.advance_id DESC

SELECT * FROM hr_employee_advance
WHERE tenant_id = #{tenantId} AND advance_id = #{advanceId}
FOR UPDATE
